import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isWarping, setIsWarping] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsWarping(true), 3500);
    const finish = setTimeout(onComplete, 4500);
    return () => { clearTimeout(timer); clearTimeout(finish); };
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-[#A1AED1] flex items-center justify-center relative overflow-hidden">

      {/* 1. TEXTURE: Industrial Grain */}
      <div className="absolute inset-0 grain-overlay pointer-events-none" />

      <div className={isWarping ? "animate-warp" : "animate-reveal"}>
        <div className="flex flex-col items-center">

          {/* THE LOGO: Beet Red */}
          <div className="relative flex items-center">
            <motion.h1 
              initial={{ letterSpacing: "-0.5em", opacity: 0 }}
              animate={{ letterSpacing: "0.1em", opacity: 1 }}
              transition={{ duration: 2, ease: "easeOut" }}
              className="text-[12rem] md:text-[20rem] font-[1000] text-[#AB1717] italic tracking-tighter leading-none select-none"
            >
              T
              <span className="text-[#AB1717] relative inline-block mx-[-10px] drop-shadow-[0_10px_30px_rgba(171,23,23,0.3)]">
                2
              </span>
              T
            </motion.h1>
          </div>

          {/* THE SUBTITLE: Grassy Green */}
          <motion.div 
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 1.5, duration: 1 }}
            className="flex items-center mt-[-30px]"
          >
            <span className="text-[#47510B] font-black text-2xl tracking-[1em] uppercase italic ml-[1em]">
              Worker
            </span>
          </motion.div>
        </div>
      </div>

      {/* 3. TACTICAL OVERLAY: Lenin Blue */}
      <div className="absolute bottom-12 w-full px-16 flex justify-between items-end">
        <div className="flex flex-col font-mono text-[10px] text-[#003366] font-bold gap-1">
          <span className="opacity-60">LAT_REF: 40.7128N</span>
          <span className="opacity-60">LON_REF: 74.0060W</span>
          <span className="font-black border-t border-[#003366]/20 pt-1">SECURE_WORKER_LINK</span>
        </div>

        <motion.span 
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="text-[#003366] font-[1000] text-2xl italic"
        >
          0.04
        </motion.span>
      </div>
    </div>
  );
};

export default WorkerSplash;
